package wazevo_test

import (
	"context"
	_ "embed"
	"runtime"
	"testing"

	"github.com/tetratelabs/wazero"
	"github.com/tetratelabs/wazero/api"
	"github.com/tetratelabs/wazero/experimental"
	"github.com/tetratelabs/wazero/internal/engine/wazevo"
	"github.com/tetratelabs/wazero/internal/platform"
	"github.com/tetratelabs/wazero/internal/testing/require"
	"github.com/tetratelabs/wazero/internal/wasm"
)

// shadowFrameWasm was generated by the following:
//
//	cd testdata; wat2wasm --enable-all shadow_frame.wat
//
//go:embed testdata/shadow_frame.wasm
var shadowFrameWasm []byte

// TestShadowFrameBalance checks that every frame releases the shadow slots it
// reserved. A raise is what can get this wrong: it skips the epilogue of every
// frame it unwinds, so those frames never release anything and the depth has
// to be restored from the try_table checkpoint instead. Left unbalanced the
// shadow stack grows for as long as a call keeps catching, and a handler
// addresses its slots from the wrong base. A tail call the backend lowers as a
// plain call (stack arguments) must likewise release its frame's slots once.
func TestShadowFrameBalance(t *testing.T) {
	if !platform.CompilerSupported() {
		t.Skip()
	}
	ctx := context.Background()
	cfg := wazero.NewRuntimeConfigCompiler().
		WithCoreFeatures(api.CoreFeaturesV2 | experimental.CoreFeaturesExceptionHandling | experimental.CoreFeaturesTailCall)
	r := wazero.NewRuntimeWithConfig(ctx, cfg)
	defer r.Close(ctx)

	mod, err := r.InstantiateWithConfig(ctx, shadowFrameWasm,
		wazero.NewModuleConfig().WithStartFunctions())
	require.NoError(t, err)

	for _, tc := range []struct {
		name     string
		expected int32 // completed calls to $catching
	}{
		{name: "unwind_once", expected: 1},
		{name: "unwind_many", expected: 100},
		{name: "tail_call_stack_args", expected: 1},
		{name: "tail_call_regs", expected: 1},
	} {
		t.Run(tc.name, func(t *testing.T) {
			f := mod.ExportedFunction(tc.name)
			res, err := f.Call(ctx)
			require.NoError(t, err)
			require.Equal(t, tc.expected, api.DecodeI32(res[0]))
			require.Equal(t, uintptr(0), wazevo.ShadowRefsTopOf(f),
				"frames left shadow slots reserved after the call returned")
		})
	}
}

// TestShadowFrameTailCallRoots checks that a tail callee roots its reference
// params without unrooting one it has not reached yet. The callee's slots
// reuse the caller's released ones, so storing an earlier param can overwrite
// the caller's only root of a later one; a collection before that later param
// is stored then frees it. The hook collects after every shadow store and
// reuses the freed memory, so a dangling exnref reads back as a filler.
func TestShadowFrameTailCallRoots(t *testing.T) {
	if !platform.CompilerSupported() {
		t.Skip()
	}
	ctx := context.Background()
	cfg := wazero.NewRuntimeConfigCompiler().
		WithCoreFeatures(api.CoreFeaturesV2 | experimental.CoreFeaturesExceptionHandling | experimental.CoreFeaturesTailCall)
	r := wazero.NewRuntimeWithConfig(ctx, cfg)
	defer r.Close(ctx)

	mod, err := r.InstantiateWithConfig(ctx, shadowFrameWasm,
		wazero.NewModuleConfig().WithStartFunctions())
	require.NoError(t, err)

	f := mod.ExportedFunction("tail_call_overlap")
	wazevo.SetShadowStoreHook(f, churnExceptions)

	res, err := f.Call(ctx)
	require.NoError(t, err)
	require.Equal(t, int32(22), api.DecodeI32(res[0])) // the second exception's param
}

// churnExceptions collects, then allocates exceptions over the freed memory.
// They carry a different tag, so a dangling exnref fails to match its catch.
func churnExceptions() {
	runtime.GC()

	const fillerCount = 1 << 12 // enough to reuse the span of a freed exception
	tag := &wasm.TagInstance{Type: &wasm.FunctionType{Params: []wasm.ValueType{wasm.ValueTypeI32}}}
	fillers := make([]*wasm.Exception, fillerCount)
	for i := range fillers {
		fillers[i] = &wasm.Exception{Tag: tag, Params: []uint64{0xdead}}
	}
	runtime.KeepAlive(fillers)
}
